{
  "items": [
    {
      "name": "MvPolynomial.pderiv",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] (i : σ) : Derivation R (MvPolynomial σ R) (MvPolynomial σ R)",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_X_self",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] (i : σ) : (MvPolynomial.pderiv i) (MvPolynomial.X i) = 1",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_X_of_ne",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] {i j : σ} (h : j ≠ i) : (MvPolynomial.pderiv i) (MvPolynomial.X j) = 0",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_def",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] [DecidableEq σ] (i : σ) : MvPolynomial.pderiv i = MvPolynomial.mkDerivation R (Pi.single i 1)",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_eq_zero_of_notMem_vars",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] {i : σ} {f : MvPolynomial σ R} (h : i ∉ f.vars) : (MvPolynomial.pderiv i) f = 0",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_one",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] {i : σ} : (MvPolynomial.pderiv i) 1 = 0",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_X",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] [DecidableEq σ] (i j : σ) : (MvPolynomial.pderiv i) (MvPolynomial.X j) = Pi.single i 1 j",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_C",
      "type": " {R : Type u} {σ : Type v} {a : R} [CommSemiring R] {i : σ} : (MvPolynomial.pderiv i) (MvPolynomial.C a) = 0",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.commute_pderiv",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] (i j : σ) : Function.Commute ⇑(MvPolynomial.pderiv i) ⇑(MvPolynomial.pderiv j)",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.coeff_pderiv",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] {i : σ} (p : MvPolynomial σ R) (m : σ →₀ ℕ) : ((MvPolynomial.pderiv i) p).coeff m = p.coeff (m + fun₀ | i => 1) * (↑(m i) + 1)",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_monomial_single",
      "type": " {R : Type u} {σ : Type v} {a : R} [CommSemiring R] {i : σ} {n : ℕ} : (MvPolynomial.pderiv i) ((MvPolynomial.monomial fun₀ | i => n) a) = (MvPolynomial.monomial fun₀ | i => n - 1) (a * ↑n)",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_monomial",
      "type": " {R : Type u} {σ : Type v} {a : R} {s : σ →₀ ℕ} [CommSemiring R] {i : σ} : (MvPolynomial.pderiv i) ((MvPolynomial.monomial s) a) = (MvPolynomial.monomial (s - fun₀ | i => 1)) (a * ↑(s i))",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    }
  ]
}
